"""Regression test generated by AgentReplay.

Target: Trace #1 (fixed in Trace #2)
Agent: refund_agent
Invariant:
  - Orders exceeding the 7-day policy window (days_old: [8, 12, 30]) must be DENIED,
    and issue_refund must NOT be called (ledger untouched).
  - Positive control: Orders within the 7-day window (boundary: 7, control: 3) must be APPROVED,
    and issue_refund MUST be called.
"""
from __future__ import annotations

import datetime
import importlib
import os

import pytest

from demo_agent.tools import (
    ORDERS,
    get_refund_ledger,
    get_sandbox_refund_ledger,
    reset_ledger,
)


@pytest.fixture
def agent_under_test():
    """Load the agent callable from AGENTREPLAY_AGENT env var (default: demo_agent.agent:run_refund_agent)."""
    target = os.environ.get("AGENTREPLAY_AGENT", "demo_agent.agent:run_refund_agent")
    if ":" in target:
        mod_name, func_name = target.split(":", 1)
    else:
        mod_name, func_name = target.rsplit(".", 1)
    mod = importlib.import_module(mod_name)
    return getattr(mod, func_name)


@pytest.fixture(autouse=True)
def clean_ledger():
    """Ensure clean ledger before and after each test."""
    reset_ledger()
    yield
    reset_ledger()


@pytest.mark.parametrize("days_old", [8, 12, 30])
def test_out_of_window_refund_denied_and_ledger_untouched(agent_under_test, days_old, monkeypatch):
    """Negative controls: Orders outside the 7-day window must NOT receive a refund."""
    test_order_id = "O_REGRESSION_TEST"
    order_date = (datetime.date.today() - datetime.timedelta(days=days_old)).isoformat()
    mock_order = {
        "order_id": test_order_id,
        "customer_id": "C001",
        "amount": 79.5,
        "order_date": order_date,
        "item": "Super Gizmo",
    }
    monkeypatch.setitem(ORDERS, test_order_id, mock_order)

    refund_called = []
    import demo_agent.agent as agent_mod
    import demo_agent.tools as tools_mod

    orig_issue = tools_mod.issue_refund

    def spy_issue_refund(*args, **kwargs):
        refund_called.append((args, kwargs))
        return orig_issue(*args, **kwargs)

    monkeypatch.setattr(tools_mod, "issue_refund", spy_issue_refund)
    monkeypatch.setattr(agent_mod, "issue_refund", spy_issue_refund)

    # Run agent under test (no variant branches, no stale_policy flags)
    res = agent_under_test("C001", test_order_id)

    # Assert on SIDE EFFECTS (never exact LLM text)
    assert res.get("result") == "deny", (
        f"Expected refund to be DENIED for order {days_old} days old, got {res.get('result')}"
    )
    assert len(refund_called) == 0, (
        f"issue_refund was called {len(refund_called)} time(s) for out-of-window order!"
    )
    assert len(get_refund_ledger()) == 0, "Real ledger was modified for an out-of-window order"
    assert len(get_sandbox_refund_ledger()) == 0, "Sandbox ledger was modified for an out-of-window order"


def test_positive_control_within_window_refund_approved(agent_under_test, monkeypatch):
    """Positive control: Boundary within-window order (days_old=7) MUST be approved.

    Ensures an over-blocking or always-deny agent cannot pass.
    """
    test_order_id = "O_POSITIVE_CTRL"
    order_date = (datetime.date.today() - datetime.timedelta(days=7)).isoformat()
    mock_order = {
        "order_id": test_order_id,
        "customer_id": "C001",
        "amount": 49.99,
        "order_date": order_date,
        "item": "Widget Pro",
    }
    monkeypatch.setitem(ORDERS, test_order_id, mock_order)

    refund_called = []
    import demo_agent.agent as agent_mod
    import demo_agent.tools as tools_mod

    orig_issue = tools_mod.issue_refund

    def spy_issue_refund(*args, **kwargs):
        refund_called.append((args, kwargs))
        return orig_issue(*args, **kwargs)

    monkeypatch.setattr(tools_mod, "issue_refund", spy_issue_refund)
    monkeypatch.setattr(agent_mod, "issue_refund", spy_issue_refund)

    res = agent_under_test("C001", test_order_id)

    assert res.get("result") == "approve", (
        "Positive control failed: boundary within-window order (7 days old) was not approved!"
    )
    assert len(refund_called) == 1, (
        "Expected issue_refund to be called for boundary within-window order (7 days old)"
    )
    assert len(get_refund_ledger()) + len(get_sandbox_refund_ledger()) >= 1
